import{_ as t,o as i,c as a,a0 as n}from"./chunks/framework.DB31oXgM.js";const h=JSON.parse('{"title":"ADR 002: Server Authority and Fixed-Point (Q16.16) Determinism","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-state-authority-and-determinism.md","filePath":"adr/002-state-authority-and-determinism.md"}'),o={name:"adr/002-state-authority-and-determinism.md"};function r(s,e,d,l,c,m){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-002-server-authority-and-fixed-point-q16-16-determinism" tabindex="-1">ADR 002: Server Authority and Fixed-Point (Q16.16) Determinism <a class="header-anchor" href="#adr-002-server-authority-and-fixed-point-q16-16-determinism" aria-label="Permalink to &quot;ADR 002: Server Authority and Fixed-Point (Q16.16) Determinism&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Multiplayer state desynchronization occurs when different clients compute slightly diverging coordinates, velocities, or collision outcomes. Standard IEEE 754 floating-point operations vary across CPU architectures, compilers, and JavaScript JIT engines. Furthermore, client-reported positions enable teleportation and speed-hack vulnerabilities.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Arithmetic Representation</strong>: All kinematic math uses signed 32-bit fixed-point numbers with 16 fractional bits (<code>FixedI32</code>).</li><li><strong>Strict Server Authority</strong>: Clients only transmit raw input bitmasks and analog stick deltas; the server alone calculates authoritative <code>WorldState</code> snapshots and collision outcomes.</li><li><strong>Continuous State Checksumming</strong>: Continuous FNV-1a/Blake3 state hashes are computed every frame to detect sub-frame divergence immediately.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Bit-exact mathematical determinism across x86_64, ARM64, and WebAssembly/V8 engines.</li><li>Complete mitigation of position-spoofing and speed-hacking exploits.</li></ul>',9)])])}const p=t(o,[["render",r]]);export{h as __pageData,p as default};
